 ?>"><input class="form-control nm-score score-input" type="number" min="0" max="100" step="0.01" name="nilai[<?= (int)$s['id'] ?>][<?= (int)$c['id'] ?>]" aria-label="<?= sanitize($c['nama_komponen'].' '.$s['nama_lengkap']) ?>" value="<?= $value!==null?number_format($value,2,'.',''):'' ?>" <?= !$manual?'disabled':'' ?>><?php if($auto!==null): ?><span class="score-label small text-muted d-block mt-1"><?= $manual?'Manual':'Otomatis' ?></span><button type="button" class="score-toggle btn btn-link btn-sm px-0" aria-pressed="<?= $manual?'true':'false' ?>"><?= $manual?'Kembali ke Otomatis':'Isi Manual' ?></button><?php endif ?></td><?php endforeach ?><td class="rekap-final"><strong><?= $ready?($complete?number_format($total,2):'Belum lengkap'):'Bobot belum 100%' ?></strong></td></tr><?php endforeach ?><?php if(!$students): ?><tr><td colspan="<?= count($components)+2 ?>" class="text-center text-muted py-5">Belum ada siswa di kelas ini.</td></tr><?php endif ?></tbody></table></div><div class="rekap-save p-3 border-top"><span class="rekap-save-note"><i class="fa-solid fa-pen-to-square me-2" aria-hidden="true"></i>Setelah mengubah nilai, simpan perubahan Anda.</span><button class="btn btn-primary" <?= !$ready||!$students?'disabled':'' ?>><i class="fa-solid fa-check me-2" aria-hidden="true"></i>Simpan Perubahan Nilai</button></div></form></section>
